UPDATE user_problem_note
SET outline_json = #{outlineJson, typeHandler=org.congcong.algomentor.agent.persistence.postgres.json.JsonbTypeHandler},
    note_markdown = #{noteMarkdown},
    revision = revision + 1,
    updated_at = #{now}
WHERE user_id = #{userId}
  AND problem_slug = #{problemSlug}
  AND revision = #{expectedRevision}
RETURNING

